class Solution {
    public long countBigDrops(int[] prices) {
        long count = 0;
        for (int i = 0; i < prices.length; i++)
            for (int j = i + 1; j < prices.length; j++)
                if (prices[i] > 2L * prices[j]) count++;
        return count;
    }
}

