class Solution:
    def countBigDrops(self, prices: List[int]) -> int:
        a, buf = prices[:], [0] * len(prices)
        def sort(lo, hi):
            if hi - lo <= 1:
                return 0
            mid = (lo + hi) // 2
            count = sort(lo, mid) + sort(mid, hi)
            j = mid
            for i in range(lo, mid):
                while j < hi and a[i] > 2 * a[j]:
                    j += 1
                count += j - mid
            i, j, k = lo, mid, lo
            while i < mid and j < hi:
                if a[i] <= a[j]:
                    buf[k] = a[i]; i += 1
                else:
                    buf[k] = a[j]; j += 1
                k += 1
            buf[k:k + mid - i] = a[i:mid]
            k += mid - i
            buf[k:k + hi - j] = a[j:hi]
            a[lo:hi] = buf[lo:hi]
            return count
        return sort(0, len(a))

