class Solution {
    private int[] a, buf;

    public long countBigDrops(int[] prices) {
        a = prices.clone();
        buf = new int[a.length];
        return sort(0, a.length);
    }

    private long sort(int lo, int hi) {
        if (hi - lo <= 1) return 0;
        int mid = (lo + hi) >>> 1;
        long count = sort(lo, mid) + sort(mid, hi);
        int j = mid;
        for (int i = lo; i < mid; i++) {
            while (j < hi && a[i] > 2L * a[j]) j++;
            count += j - mid;
        }
        int i = lo, k = lo;
        j = mid;
        while (i < mid && j < hi) buf[k++] = a[i] <= a[j] ? a[i++] : a[j++];
        while (i < mid) buf[k++] = a[i++];
        while (j < hi) buf[k++] = a[j++];
        System.arraycopy(buf, lo, a, lo, hi - lo);
        return count;
    }
}

