code.c:
static long long drops(int* a, int* buf, int lo, int hi) {
    if (hi - lo <= 1) return 0;
    int mid = lo + (hi - lo) / 2;
    long long count = drops(a, buf, lo, mid) + drops(a, buf, mid, hi);
    int j = mid;
    for (int i = lo; i < mid; i++) {
        while (j < hi && a[i] > 2LL * a[j]) j++;
        count += j - mid;
    }
    int i = lo, k = lo;
    j = mid;
    while (i < mid && j < hi) buf[k++] = a[i] <= a[j] ? a[i++] : a[j++];
    while (i < mid) buf[k++] = a[i++];
    while (j < hi) buf[k++] = a[j++];
    memcpy(a + lo, buf + lo, (hi - lo) * sizeof(int));
    return count;
}

long long countBigDrops(int* prices, int pricesSize) {
    int* a = malloc(pricesSize * sizeof(int));
    int* buf = malloc(pricesSize * sizeof(int));
    memcpy(a, prices, pricesSize * sizeof(int));
    long long count = drops(a, buf, 0, pricesSize);
    free(a); free(buf);
    return count;
}
